### 2. WordCount 流处理（KStream 基础）

```java
import org.apache.kafka.streams.*;
import org.apache.kafka.streams.kstream.*;
import java.util.Properties;

public class WordCountApp {
    public static void main(String[] args) {
        Properties props = new Properties();
        props.put(StreamsConfig.APPLICATION_ID_CONFIG, "wordcount-app");
        props.put(StreamsConfig.BOOTSTRAP_SERVERS_CONFIG, "localhost:9092");
        props.put(StreamsConfig.DEFAULT_KEY_SERDE_CLASS_CONFIG, Serdes.String().getClass());
        props.put(StreamsConfig.DEFAULT_VALUE_SERDE_CLASS_CONFIG, Serdes.String().getClass());
        // 生产环境推荐 RocksDB 状态存储
        props.put(StreamsConfig.ROCKSDB_CONFIG_SETTER_CLASS_CONFIG, CustomRocksDBConfig.class);
        // Exactly-Once 语义
        props.put(StreamsConfig.PROCESSING_GUARANTEE_CONFIG, StreamsConfig.EXACTLY_ONCE_V2);

        StreamsBuilder builder = new StreamsBuilder();

        // 1. 从 input topic 读取 KStream
        KStream<String, String> textLines = builder.stream("input-text");

        // 2. 分词 + flatMap
        KStream<String, String> words = textLines
            .flatMapValues(line -> Arrays.asList(line.toLowerCase().split("\\W+")));

        // 3. 按 word 分组（word 作为 key）
        KGroupedStream<String, String> grouped = words.groupBy((k, word) -> word);

        // 4. 计数 → KTable
        KTable<String, Long> wordCounts = grouped.count(Materialized.as("word-count-store"));

        // 5. 输出到 output topic
        wordCounts.toStream().to("output-word-count",
            Produced.with(Serdes.String(), Serdes.Long()));

        KafkaStreams streams = new KafkaStreams(builder.build(), props);
        streams.start();

        // 优雅关闭
        Runtime.getRuntime().addShutdownHook(new Thread(streams::close));
    }
}
```

### 3. 窗口聚合（Tumbling Window + KTable）

```java
// 每分钟统计各用户的订单金额总和
KStream<String, Order> orders = builder.stream("orders");

KTable<Windowed<String>, Double> windowedSum = orders
    .filter((k, v) -> v != null)
    .groupBy((k, v) -> v.getUserId(),  // 按 userId 分组
        Grouped.with(Serdes.String(), orderSerde))
    .windowedBy(TimeWindows.ofSizeAndGrace(
        Duration.ofMinutes(1),    // 窗口大小 1 分钟
        Duration.ofSeconds(5)))    // grace period 5 秒
    .aggregate(
        () -> 0.0,                                          // 初始值
        (userId, order, agg) -> agg + order.getAmount(),     // 聚合逻辑
        Materialized.<String, Double>as("order-sum-store")
            .withKeySerde(Serdes.String())
            .withValueSerde(Serdes.Double())
    );

// 输出窗口结果
windowedSum.toStream()
    .map((windowedKey, total) -> {
        String windowStart = Instant.ofEpochMilli(windowedKey.window().start()).toString();
        return KeyValue.pair(windowedKey.key() + "@" + windowStart, total);
    })
    .to("order-window-sum");
```

### 4. KStream + KTable Join（实时维度关联）

```java
// 事实流：订单事件
KStream<String, OrderEvent> orderStream = builder.stream("order-events");

// 维度表：用户信息（KTable，按 userId upsert）
KTable<String, UserInfo> userTable = builder.table("users",
    Consumed.with(Serdes.String(), userInfoSerde));

// 流表 Join：为每条订单补充用户名称
KStream<String, EnrichedOrder> enriched = orderStream.join(
    userTable,
    (order, user) -> new EnrichedOrder(order, user.getName(), user.getCity())
);

enriched.to("enriched-orders");
```

